"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('web', 59), ('core', 11), ('ops', 3), ('core', 55), ('data', 5), ('web', 41), ('ops', 6)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)


def feed_tickets():
    """Endless feed of tickets: repeats the stored rows for ever."""
    while True:
        for team, hours in ROWS:
            yield Ticket(team, hours)

