"""Windows over the tickets feed."""
import itertools


def summarize_window(feed, size):
    """Read the next `size` tickets from the feed and return (peak hours, list of hours).

    The feed may be endless. Exactly `size` items are read from it.
    """
    window = itertools.islice(feed, size)
    peak = max(x.hours for x in window)
    values = [x.hours for x in window]
    return peak, values


def group_by_team(tickets):
    """Return a dict from team to the list of tickets with that team."""
    groups = {}
    for x in tickets:
        groups.setdefault(x.team, []).append(x)
    return groups


def team_names(tickets):
    """Return the distinct team values, in first-seen order."""
    names = []
    for x in tickets:
        if x.team not in names:
            names.append(x.team)
    return names
